package com.bank.heap.model;

// Tracks the heap: capacity, currently used bytes, and the LIVE set.
public class HeapModel {
    private final long capacityKb;
    private long usedKb = 0;
    private long liveSetKb = 0;   // surviving objects the collector must scan

    public HeapModel(long capacityKb) { this.capacityKb = capacityKb; }

    public boolean allocate(long kb) {
        if (usedKb + kb > capacityKb) return false; // heap full → collection needed
        usedKb += kb;
        return true;
    }

    // A leak means some allocated memory stays live after collection.
    public void addLive(long kb) { liveSetKb += kb; }

    // Collection frees garbage (used - live), keeping the live set.
    public void collect() { usedKb = liveSetKb; }

    public long getCapacityKb() { return capacityKb; }
    public long getUsedKb() { return usedKb; }
    public long getLiveSetKb() { return liveSetKb; }
}
