package com.bank.heap.gc;

import com.bank.heap.model.HeapModel;

// Pause cost is proportional to the LIVE set scanned, NOT to garbage freed.
public class Collector {
    // 1 ms of pause per 1 MB (1024 KB) of live memory scanned.
    public long collect(HeapModel heap) {
        long liveMb = Math.max(1, heap.getLiveSetKb() / 1024);
        long pauseMs = liveMb; // the key relationship: pause ∝ live set
        heap.collect();
        return pauseMs;
    }
}
