package com.bank.heap.load;

import com.bank.heap.model.HeapModel;

// Models the quote-pricing hot loop: big allocations, optional leak.
public class Allocator {
    private final long perQuoteKb;
    private final boolean leak;

    public Allocator(long perQuoteKb, boolean leak) {
        this.perQuoteKb = perQuoteKb;
        this.leak = leak;
    }

    // Try to price one quote. Returns false if the heap is full (needs GC).
    public boolean priceQuote(HeapModel heap) {
        boolean ok = heap.allocate(perQuoteKb);
        if (ok && leak) {
            // 10% of each quote's memory is retained forever (cache never evicts).
            heap.addLive(perQuoteKb / 10);
        }
        return ok;
    }
}
