package com.bank.heap.sim;

import com.bank.heap.gc.Collector;
import com.bank.heap.load.Allocator;
import com.bank.heap.model.HeapModel;
import java.util.logging.Logger;

// Runs the workload, counting collections and summing pause time.
public class GcSimulator {
    private static final Logger log = Logger.getLogger(GcSimulator.class.getName());
    private final Collector collector = new Collector();

    public void run(String label, long heapMb, Allocator allocator, int quotes) {
        HeapModel heap = new HeapModel(heapMb * 1024);
        int collections = 0;
        long totalPauseMs = 0;
        long maxPauseMs = 0;

        for (int i = 0; i < quotes; i++) {
            if (!allocator.priceQuote(heap)) {
                // Heap full → stop the world and collect.
                long pause = collector.collect(heap);
                collections++;
                totalPauseMs += pause;
                maxPauseMs = Math.max(maxPauseMs, pause);
                allocator.priceQuote(heap); // retry the allocation after GC
            }
        }
        final int c = collections; final long tp = totalPauseMs;
        final long mp = maxPauseMs; final long live = heap.getLiveSetKb() / 1024;
        log.info(() -> label + ": heap=" + heapMb + "MB collections=" + c
                + " totalPause=" + tp + "ms maxPause=" + mp + "ms finalLiveSet=" + live + "MB");
    }
}
