package com.bank.heap;

import com.bank.heap.load.Allocator;
import com.bank.heap.sim.GcSimulator;
import java.util.logging.Logger;

public class HeapDemo {
    private static final Logger log = Logger.getLogger(HeapDemo.class.getName());

    public static void main(String[] args) {
        GcSimulator sim = new GcSimulator();
        int quotes = 20000;

        log.info("=== leaky, high-allocation workload ===");
        Allocator leaky = new Allocator(256, true);
        // Small heap: frequent but SHORT pauses.
        sim.run("small-heap", 512, new Allocator(256, true), quotes);
        // Large heap: FEWER but much LONGER pauses (bigger live set scanned).
        sim.run("large-heap", 4096, new Allocator(256, true), quotes);

        log.info("=== the REAL fix: reduce allocation + stop the leak ===");
        // Lower allocation per quote AND no leak → tiny live set, tiny pauses.
        sim.run("fixed-code", 512, new Allocator(32, false), quotes);
    }
}
